// P2 step 8 — trajectory failure tags, generated by a model and marked as
// such. The plan dropped the human gold set (user decision, 2026-10-26), so
// these tags are explicitly NON-GOLD evidence:
//
//   • they never set, clear or soften `hardViolation` — that stays with the
//     deterministic contract + events (ADR-07 / §7.2 "不读 narrate 标签");
//   • they never enter a score, a ranking or the four-cell reading;
//   • every record carries `nonGold: true`, the model that produced it and the
//     contract version it was written against, so the UI can say so.
//
// The prompt never sees `failure.tag` events (the scorer's own narrator
// labels) or the scorer's `failureTags`: the point is an independent read of
// the recorded steps, not a paraphrase of the existing verdict.
import { MAST_HINT, type MastTag } from '../../shared/mast'
import type { HarnessEvent } from '../../shared/events'
import type { TrajectoryTag, TrajectoryTagRecord, TrajectoryVerdictDetail } from '../../shared/trajectory'
import { getPlaygroundDb, liveDbFile } from './liveDb'
import { chatCompletionWithFallback, resolveChatTarget } from './llmClient'
import { llmWarn } from './jevLog'

const PROMPT_VERSION = 'traj-tags-1'
const TAG_ORDER: MastTag[] = [
  'premature-victory', 'weak-grounding', 'long-horizon-decay', 'spec-misinterpretation',
  'fabricated-citation', 'scope-violation', 'step-repetition', 'reasoning-action-mismatch',
  'unaware-of-stopping', 'task-derailment', 'fail-to-clarify', 'context-loss', 'other',
]

function isTag(v: unknown): v is MastTag {
  return typeof v === 'string' && (TAG_ORDER as readonly string[]).includes(v)
}

let tableFor: string | null = null
function ensureTable(): void {
  // The DB path is process-global and tests switch it; keying on the path keeps
  // a switched database from inheriting a "table already exists" flag.
  const file = liveDbFile()
  if (tableFor === file) return
  getPlaygroundDb().exec(`
    CREATE TABLE IF NOT EXISTS pg_trajectory_tags (
      run_id TEXT NOT NULL,
      contract_version TEXT NOT NULL,
      payload_json TEXT NOT NULL,
      model TEXT NOT NULL,
      created_at TEXT NOT NULL,
      PRIMARY KEY (run_id, contract_version)
    )`)
  tableFor = file
}

/** Tests point the DB at :memory: — the table flag must reset with it. */
export function resetTrajectoryTagCache(): void {
  tableFor = null
}

export function getTrajectoryTags(runId: string): TrajectoryTagRecord | null {
  ensureTable()
  const row = getPlaygroundDb()
    .prepare('SELECT payload_json FROM pg_trajectory_tags WHERE run_id = ? ORDER BY created_at DESC LIMIT 1')
    .get(runId) as { payload_json: string } | undefined
  if (!row) return null
  try {
    return JSON.parse(row.payload_json) as TrajectoryTagRecord
  } catch {
    return null
  }
}

function saveTrajectoryTags(record: TrajectoryTagRecord): void {
  ensureTable()
  getPlaygroundDb()
    .prepare(
      `INSERT INTO pg_trajectory_tags (run_id, contract_version, payload_json, model, created_at)
       VALUES (?, ?, ?, ?, ?)
       ON CONFLICT(run_id, contract_version) DO UPDATE SET payload_json = excluded.payload_json,
         model = excluded.model, created_at = excluded.created_at`,
    )
    .run(record.runId, record.contractVersion, JSON.stringify(record), record.model, record.generatedAt)
}

function clip(s: string, n: number): string {
  const t = s.replace(/\s+/g, ' ').trim()
  return t.length <= n ? t : `${t.slice(0, n)}…`
}

/**
 * A compact, honest view of the run: the task, what the contract found, and
 * the steps themselves. Deliberately excludes failure.tag and the scorer's
 * tags so the model cannot simply echo the existing verdict.
 */
export function buildTagDigest(input: {
  taskId: string
  taskTitle: string
  domain: string
  answer: string | null
  events: HarnessEvent[]
  verdict: TrajectoryVerdictDetail
}): string {
  const { taskId, taskTitle, domain, answer, events, verdict } = input
  const lines: string[] = []
  lines.push(`任务：${taskId} · ${taskTitle}（域：${domain}）`)
  lines.push(
    `轨迹读数：终态=${verdict.terminalSuccess === true ? '成功' : verdict.terminalSuccess === false ? '失败' : '未知'}，` +
      `CSR=${verdict.csr === null ? '未知' : verdict.csr.toFixed(2)}，硬违规=${verdict.hardViolation ? '有' : '无'}，` +
      `首次偏离=${verdict.firstDivergence ?? '无'}`,
  )
  const cpLine = verdict.checkpoints
    .map((c) => `${c.id}=${c.unknown ? '未知' : c.completed ? '已过' : '未过'}`)
    .join('，')
  if (cpLine) lines.push(`检查点：${cpLine}`)
  lines.push('步骤：')
  let stepNo = 0
  for (const s of events) {
    if (s.type === 'failure.tag') continue
    if (s.type === 'run.started') continue
    if (typeof (s as { step?: number }).step === 'number') stepNo = (s as { step: number }).step
    switch (s.type) {
      case 'tool.call':
        lines.push(`  [步${stepNo}] 调用 ${s.tool}(${clip(s.argsSummary, 120)})`)
        break
      case 'tool.result':
        lines.push(`  [步${stepNo}] 结果 ${s.tool}: ${clip(s.summary, 120)}`)
        break
      case 'model.response':
        if (s.thought.trim().length > 0) lines.push(`  [步${stepNo}] 模型输出：${clip(s.thought, 300)}`)
        else lines.push(`  [步${stepNo}] 模型输出：（空，stopReason=${s.stopReason}）`)
        break
      case 'router.decision':
        lines.push(`  [步${stepNo}] 路由 ${s.tool} → ${s.route}（${s.matchedRule}）`)
        break
      case 'permission.denied':
        lines.push(`  [步${stepNo}] 权限拒绝 ${s.scope}：${clip(s.reason, 120)}`)
        break
      case 'permission.granted':
        lines.push(`  [步${stepNo}] 权限放行 ${s.scope}`)
        break
      case 'hook.decision':
        lines.push(`  [步${stepNo}] 钩子 ${s.hook}：${s.verdict}（${clip(s.reason, 100)}）`)
        break
      case 'verifier.verdict':
        lines.push(`  [步${stepNo}] 验证器 ${s.verifier}：${s.verdict}（${clip(s.reason, 120)}）`)
        break
      case 'sensor.lint':
        lines.push(`  [步${stepNo}] 检查 ${s.lint}：${s.verdict}（${clip(s.reason, 100)}）`)
        break
      case 'legal.assertion':
        lines.push(`  [步${stepNo}] 法律断言 ${s.label}：${clip(s.claimText, 100)} ← ${clip(s.citedAuthority, 60)}`)
        break
      case 'compact.boundary':
        lines.push(`  [步${stepNo}] 上下文压缩`)
        break
      case 'harness.mutation':
        lines.push(`  [步${stepNo}] harness 变更：${s.commitId}`)
        break
      default:
        break
    }
  }
  if (answer) lines.push(`最终答案（截断）：${clip(answer, 800)}`)
  return lines.join('\n')
}

const SYSTEM = [
  '你在给一条已记录的 agent 轨迹打失败标签，供评审参考。',
  '这些标签不是金标准：它们只是模型给出的旁证，不能推翻确定性的轨迹判定（硬违规只由契约+事件决定）。',
  '',
  '标签只能从下面这组里选（一次可给多个，也可给空数组表示没有发现失败）：',
  ...TAG_ORDER.map((t) => `- ${t}: ${MAST_HINT[t]}`),
  '',
  '要求：',
  '1. 只依据轨迹里出现过的步骤与证据，不臆测没有出现的动作；',
  '2. 每条标签给出 confidence（0-1）、why（一句话，引用具体步骤或证据）、step（最相关的步号，没有就 null）；',
  '3. 判断对象是"过程"，不是"答案对不对"：答案正确性由判定模型负责，这里不要打分；',
  '4. 输出严格 JSON：{"tags":[{"tag":"...","confidence":0.8,"why":"...","step":3}],"summary":"一句话"}。',
  '5. 没有明显失败就给 {"tags":[],"summary":"..."}，不要为了凑数硬打标签。',
].join('\n')


/**
 * Parse a model response into a tag record. Pure and exported so the guardrails
 * (unknown tags dropped, confidence clamped, `nonGold` always true) can be
 * tested without a provider.
 */
export function parseTagResponse(
  text: string,
  meta: { runId: string; contractId: string; contractVersion: string; providerId: string; model: string; generatedAt: string },
): { ok: true; record: TrajectoryTagRecord } | { ok: false; error: string } {
  let parsed: { tags?: unknown; summary?: unknown }
  try {
    parsed = JSON.parse(text) as { tags?: unknown; summary?: unknown }
  } catch {
    return { ok: false, error: 'model did not return JSON' }
  }
  const rawTags = Array.isArray(parsed.tags) ? parsed.tags : []
  const tags: TrajectoryTag[] = []
  for (const t of rawTags) {
    if (!t || typeof t !== 'object') continue
    const o = t as Record<string, unknown>
    if (!isTag(o.tag)) continue // a hallucinated tag is dropped, never coerced
    const confidence = typeof o.confidence === 'number' && o.confidence >= 0 && o.confidence <= 1 ? o.confidence : 0.5
    const step = typeof o.step === 'number' && Number.isFinite(o.step) ? o.step : null
    tags.push({ tag: o.tag, confidence, why: typeof o.why === 'string' ? o.why.slice(0, 400) : '', step })
  }
  return {
    ok: true,
    record: {
      ...meta,
      nonGold: true,
      promptVersion: PROMPT_VERSION,
      tags,
      summary: typeof parsed.summary === 'string' ? parsed.summary.slice(0, 600) : '',
    },
  }
}

/** Exposed for the round-trip test; the route never calls it directly. */
export function saveTagRecordForTest(record: TrajectoryTagRecord): void {
  saveTrajectoryTags(record)
}

/**
 * Tag one recorded run. Never throws on a model failure: returns an error
 * string so the route can show "tagging unavailable" without touching the
 * trajectory reading.
 */
export async function tagTrajectory(input: {
  runId: string
  taskId: string
  taskTitle: string
  domain: string
  answer: string | null
  events: HarnessEvent[]
  verdict: TrajectoryVerdictDetail
}): Promise<{ ok: true; record: TrajectoryTagRecord } | { ok: false; error: string }> {
  const target = resolveChatTarget()
  if ('error' in target) return { ok: false, error: target.error }
  const digest = buildTagDigest(input)
  let text = ''
  try {
    const res = await chatCompletionWithFallback(
      target,
      {
        messages: [
          { role: 'system', content: SYSTEM },
          { role: 'user', content: digest },
        ],
        responseFormat: { type: 'json_object' },
        temperature: 0,
        maxTokens: 800,
      },
      { allowFallback: true },
    )
    text = res.text
  } catch (err) {
    const msg = err instanceof Error ? err.message : String(err)
    llmWarn(`trajectory tags ← ${target.providerId}/${target.model}: ${msg}`)
    return { ok: false, error: msg }
  }

  const parsed = parseTagResponse(text, {
    runId: input.runId,
    contractId: input.verdict.contractId,
    contractVersion: input.verdict.contractVersion,
    providerId: target.providerId,
    model: target.model,
    generatedAt: new Date().toISOString(),
  })
  if (!parsed.ok) return parsed
  saveTrajectoryTags(parsed.record)
  return { ok: true, record: parsed.record }
}

